SET search_path TO endurancetrio_hub;

-- Update existing race's result_status
UPDATE race SET race_status = 'COMPLETED', result_status = 'COMPLETE' WHERE id IN (77, 78, 79, 80, 81);

-- Update existing athletes
UPDATE athlete SET known_name = 'Filipe Mello' WHERE id = 174;

